using HartsyInference.Core.Backends;
using HartsyInference.Core.Backends.Cpu;
using HartsyInference.Core.Tensors;
using HartsyInference.Diffusion.Models.Denoisers.SanaWm;
using HartsyInference.ModelAssets.SafeTensors;
using Xunit;

namespace HartsyInference.Diffusion.Tests;

/// <summary>SANA-WM camera branch against the upstream torch reference on a tiny case (T=4, H_lat=2, W_lat=3, one head of
/// dim 112), generated by <c>Fixtures/generate_sana_wm_s2_cam_branch_fixture.py</c> on CPU.</summary>
public sealed class SanaWmCamBranchTests
{
    private const int Frames = 4;
    private const int LatentHeight = 2;
    private const int LatentWidth = 3;
    private const int Heads = 1;
    private const int HeadDim = 112;
    private const int Channels = Heads * HeadDim;
    private const int Tokens = Frames * LatentHeight * LatentWidth;
    private const float Tolerance = 1e-5f;

    [Fact]
    public void Forward_MatchesUpstreamReference_WithinAbsoluteTolerance()
    {
        using SafeTensorsLoader loader = LoadFixture();
        IReadOnlyDictionary<string, Tensor> fixture = loader.GetAllTensors();
        using SanaWmCamBranch branch = new(Heads, HeadDim);
        branch.LoadWeights(fixture);
        using CpuBackend backend = new();

        float[] cameraConditions = fixture["camera_conditions"].AsReadOnlySpan<float>().ToArray();
        using Tensor cam = branch.Forward(backend, fixture["x"], cameraConditions, Frames, LatentHeight, LatentWidth,
            fixture["rope_cos"], fixture["rope_sin"], fixture["beta"], fixture["decay"]);

        ReadOnlySpan<float> actual = cam.AsReadOnlySpan<float>();
        ReadOnlySpan<float> expected = fixture["expected_cam_raw"].AsReadOnlySpan<float>();
        Assert.Equal(expected.Length, actual.Length);
        float maxError = 0f;
        for (int i = 0; i < expected.Length; i++)
            maxError = MathF.Max(maxError, MathF.Abs(actual[i] - expected[i]));
        Assert.True(maxError <= Tolerance, $"max abs error {maxError:E3} exceeds {Tolerance:E0}");
    }

    [Fact]
    public void Forward_RayMatrices_MatchUpstreamDump()
    {
        using SafeTensorsLoader loader = LoadFixture();
        IReadOnlyDictionary<string, Tensor> fixture = loader.GetAllTensors();
        float[] cameraConditions = fixture["camera_conditions"].AsReadOnlySpan<float>().ToArray();
        float[] expected = fixture["ray_p"].AsReadOnlySpan<float>().ToArray();
        float[] matrices = new float[Tokens * 16];
        float[] transposed = new float[Tokens * 16];
        float[] inverse = new float[Tokens * 16];

        SanaWmCamRays.Build(cameraConditions, 1, Frames, LatentHeight, LatentWidth, matrices, transposed, inverse);

        float maxError = 0f;
        for (int i = 0; i < expected.Length; i++)
            maxError = MathF.Max(maxError, MathF.Abs(matrices[i] - expected[i]));
        Assert.True(maxError <= 1e-6f, $"ray matrix max abs error {maxError:E3}");
    }

    [Fact]
    public void Forward_BatchOfTwo_EachSampleMatchesUpstreamReference()
    {
        using SafeTensorsLoader loader = LoadFixture();
        IReadOnlyDictionary<string, Tensor> fixture = loader.GetAllTensors();
        using SanaWmCamBranch branch = new(Heads, HeadDim);
        branch.LoadWeights(fixture);
        using CpuBackend backend = new();

        float[] x = Doubled(fixture["x"]);
        float[] cameraConditions = Doubled(fixture["camera_conditions"]);
        float[] beta = Doubled(fixture["beta"]);
        float[] decay = Doubled(fixture["decay"]);
        using Tensor xBatch = Host(x, 2, Tokens, Channels);
        using Tensor betaBatch = Host(beta, 2, Heads, Frames, LatentHeight * LatentWidth);
        using Tensor decayBatch = Host(decay, 2, Heads, Frames);

        using Tensor cam = branch.Forward(backend, xBatch, cameraConditions, Frames, LatentHeight, LatentWidth,
            fixture["rope_cos"], fixture["rope_sin"], betaBatch, decayBatch);

        ReadOnlySpan<float> actual = cam.AsReadOnlySpan<float>();
        ReadOnlySpan<float> expected = fixture["expected_cam_raw"].AsReadOnlySpan<float>();
        int sample = Tokens * Channels;
        float maxError = 0f;
        for (int i = 0; i < 2 * sample; i++)
            maxError = MathF.Max(maxError, MathF.Abs(actual[i] - expected[i % sample]));
        Assert.True(maxError <= Tolerance, $"batch max abs error {maxError:E3} exceeds {Tolerance:E0}");
    }

    [Fact]
    public void Forward_WithZeroOutProjection_ReturnsExactZero()
    {
        using SafeTensorsLoader loader = LoadFixture();
        IReadOnlyDictionary<string, Tensor> fixture = loader.GetAllTensors();
        Dictionary<string, Tensor> weights = new(fixture);
        using Tensor zeroWeight = new(new TensorShape(Channels, Channels), DType.F32, DeviceKind.Cpu);
        using Tensor zeroBias = new(new TensorShape(Channels), DType.F32, DeviceKind.Cpu);
        zeroWeight.AsSpan<float>().Clear();
        zeroBias.AsSpan<float>().Clear();
        weights["out_proj_cam.weight"] = zeroWeight;
        weights["out_proj_cam.bias"] = zeroBias;

        using SanaWmCamBranch branch = new(Heads, HeadDim);
        branch.LoadWeights(weights);
        using CpuBackend backend = new();
        float[] cameraConditions = fixture["camera_conditions"].AsReadOnlySpan<float>().ToArray();
        using Tensor cam = branch.Forward(backend, fixture["x"], cameraConditions, Frames, LatentHeight, LatentWidth,
            fixture["rope_cos"], fixture["rope_sin"], fixture["beta"], fixture["decay"]);

        foreach (float value in cam.AsReadOnlySpan<float>())
            Assert.Equal(0f, value);
    }

    private static float[] Doubled(Tensor tensor)
    {
        ReadOnlySpan<float> source = tensor.AsReadOnlySpan<float>();
        float[] doubled = new float[source.Length * 2];
        source.CopyTo(doubled);
        source.CopyTo(doubled.AsSpan(source.Length));
        return doubled;
    }

    private static Tensor Host(float[] values, params int[] dims)
    {
        long[] shape = new long[dims.Length];
        for (int i = 0; i < dims.Length; i++)
            shape[i] = dims[i];
        Tensor tensor = new(new TensorShape(shape), DType.F32, DeviceKind.Cpu);
        values.AsSpan().CopyTo(tensor.AsSpan<float>());
        return tensor;
    }

    private static SafeTensorsLoader LoadFixture()
    {
        SafeTensorsLoader loader = new();
        loader.Load(Path.Combine(AppContext.BaseDirectory, "Fixtures", "sana_wm_s2_cam_branch.safetensors"));
        return loader;
    }
}
